+  inset: 0;
+  z-index: 70;
+  display: none;
+}
+
+.modal[data-open="true"] {
+  display: block;
+}
+
+.modal-backdrop {
+  position: absolute;
+  inset: 0;
+  background: rgba(15, 23, 42, 0.55);
+}
+
