+  gap: 1rem;
+}
+
+.modal-body {
+  padding: 1.15rem;
+}
+
+.amount-grid {
+  display: grid;
+  grid-template-columns: repeat(2, minmax(0, 1fr));
+  gap: 0.75rem;
+  margin-top: 0.75rem;
+}
+
+@media (min-width: 640px) {
+  .amount-grid {
+    grid-template-columns: repeat(5, minmax(0, 1fr));
+  }
+}
+
+.amount {
+  border: 1px solid rgba(27, 58, 92, 0.16);
+  background: rgba(27, 58, 92, 0.03);
+  border-radius: 14px;
+  padding: 0.75rem 0.7rem;
+  font-weight: 800;
+  letter-spacing: -0.02em;
+  transition: background 180ms ease, transform 150ms ease, border-color 180ms ease;
+}
+
+.amount:hover {
+  background: rgba(196, 30, 58, 0.08);
+  border-color: rgba(196, 30, 58, 0.25);
+  transform: translateY(-2px);
+}
+
+.amount[aria-pressed="true"] {
+  background: rgba(196, 30, 58, 0.12);
+  border-color: rgba(196, 30, 58, 0.45);
+}
+
+.field {
+  display: grid;
+  gap: 0.35rem;
+}
+
+.input {
+  border: 1px solid rgba(27, 58, 92, 0.20);
+  border-radius: 14px;
+  padding: 0.8rem 0.9rem;
+  background: #fff;
+}
+
+.input:focus {
+  outline: 3px solid rgba(196, 30, 58, 0.20);
+  border-color: rgba(196, 30, 58, 0.55);
+}
+
+.sr-only {
+  position: absolute;
+  width: 1px;
+  height: 1px;
+  padding: 0;
+  margin: -1px;
+  overflow: hidden;
+  clip: rect(0, 0, 0, 0);
+  white-space: nowrap;
+  border-width: 0;
+}
+
+/* Footer */
+footer a {
+  color: rgba(27, 58, 92, 0.78);
+}
+
+footer a:hover {
+  color: rgba(27, 58, 92, 1);
+}
+
*** End Patch
PATCH

